CREATE TABLE [dbo].[cccallsreject](	  [cal_id] INT NOT NULL IDENTITY(1,1)	, [ani] VARCHAR(15) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [dnis] VARCHAR(15) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [puerto] SMALLINT NOT NULL	, [cal_inicio] DATETIME NOT NULL DEFAULT(getdate())	, [Inbound_id] SMALLINT NOT NULL DEFAULT((-1))	, CONSTRAINT [PK_ccCallsReject] PRIMARY KEY ([cal_id] ASC))CREATE NONCLUSTERED INDEX [IX_cccallsreject] ON [dbo].[cccallsreject] ([cal_inicio] ASC)